(6523407, 969295, 135874, '<td valign="top">Love all of the squiggly colors zooming past.</td>', 'Love all of the squiggly colors zooming past.', '2011-09-01 14:16:38.000000', NULL, 1),
(6523408, 968313, 135874, '<td valign="top">I really like the concept of using an aquarium as a window. Good job!</td>', 'I really like the concept of using an aquarium as a window. Good job!', '2011-09-01 14:19:21.000000', NULL, 1),
(6523409, 969002, 135874, '<td valign="top">I really like the soft framing from the window and the silhouette from the branches and foliage.</td>', 'I really like the soft framing from the window and the silhouette from the branches and foliage.', '2011-09-01 14:21:12.000000', NULL, 1),
(6523412, 969196, 135874, '<td valign="top">Love the angry birds game! Besides the title, I also really like how the bird is in focus and everything else is blurry, even the hummingbird feeder.</td>', 'Love the angry birds game! Besides the title, I also really like how the bird is in focus and everything else is blurry, even the hummingbird feeder.', '2011-09-01 14:24:19.000000', NULL, 1),
