INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6523576, 968379, 113591, '<td valign="top">If my wif was voting, you would get 10, she loves these type of windows.</td>', 'If my wif was voting, you would get 10, she loves these type of windows.', '2011-09-01 16:31:49.000000', NULL, 1),
(6523577, 969363, 113591, '<td valign="top">Is it very near the ocean, taken in the eye of Lucy?</td>', 'Is it very near the ocean, taken in the eye of Lucy?', '2011-09-01 16:34:42.000000', NULL, 1),
(6523581, 969335, 113591, '<td valign="top">I like the OOF part more than the in-focus area. Still a nice one, 7</td>', 'I like the OOF part more than the in-focus area. Still a nice one, 7', '2011-09-01 16:40:40.000000', NULL, 1),
(6523588, 969326, 113591, '<td valign="top">I like the composition.</td>', 'I like the composition.', '2011-09-01 16:45:09.000000', NULL, 1),
(6523591, 968185, 113591, '<td valign="top">Perfect background.</td>', 'Perfect background.', '2011-09-01 16:46:42.000000', NULL, 1),
(6523649, 969025, 30861, '<td valign="top">CLARK needs validation? How bizarre!</td>', 'CLARK needs validation? How bizarre!', '2011-09-01 17:43:58.000000', NULL, 1),
(6523654, 969363, 30861, '<td valign="top">That shark is worth an extra point :-)</td>', 'That shark is worth an extra point :-)', '2011-09-01 17:46:58.000000', NULL, 1),
(6523658, 969276, 30861, '<td valign="top">this one''s my winner. 10 for you.</td>', 'this one''s my winner. 10 for you.', '2011-09-01 17:48:44.000000', NULL, 1),
(6523823, 969341, 117912, '<td valign="top">Tsk... taking pictures while driving... ;-)  interesting composition though I find myself wondering what the true subject is.</td>', 'Tsk... taking pictures while driving... ;-)  interesting composition though I find myself wondering what the true subject is.', '2011-09-01 19:34:43.000000', NULL, 1),
(6523824, 969305, 117912, '<td valign="top">Nice use of negative space - the silhouette of the sail is clearly defining and dividing the image though the person seems in my opinion to detract more than add to it.  Contre jour is fun to play with but I don''t think it''s works here with the foreground all overlapping.</td>', 'Nice use of negative space - the silhouette of the sail is clearly defining and dividing the image though the person seems in my opinion to detract more than add to it.  Contre jour is fun to play with but I don''t think it''s works here with the foreground all overlapping.', '2011-09-01 19:34:46.000000', NULL, 1),
(6523826, 968576, 117912, '<td valign="top">What a beautiful view - though hardly a bedroom window is it... the obvious wonder of the child adds so much to the feeling.</td>', 'What a beautiful view - though hardly a bedroom window is it... the obvious wonder of the child adds so much to the feeling.', '2011-09-01 19:35:13.000000', NULL, 1),
(6523828, 969025, 117912, '<td valign="top">The black and white processing works well for this photo - the dashboard would lose so much in color and the view through the windshield would distract rather than add from the composition.</td>', 'The black and white processing works well for this photo - the dashboard would lose so much in color and the view through the windshield would distract rather than add from the composition.', '2011-09-01 19:35:16.000000', NULL, 1),
(6523829, 969360, 117912, '<td valign="top">For such a strongly lit bird, how did the background get so black - the processing adds impact definitely, but at the sot of making it look unnatural.</td>', 'For such a strongly lit bird, how did the background get so black - the processing adds impact definitely, but at the sot of making it look unnatural.', '2011-09-01 19:35:18.000000', NULL, 1),
(6523830, 969198, 117912, '<td valign="top">Given time, mother nature will make herself known in any window.  The darkness in the rest of the photo leads to the window and then draws attention to the little details hiding in the darkness - certainly worth more than a cursory look.</td>', 'Given time, mother nature will make herself known in any window.  The darkness in the rest of the photo leads to the window and then draws attention to the little details hiding in the darkness - certainly worth more than a cursory look.', '2011-09-01 19:35:19.000000', NULL, 1),
(6523831, 969335, 117912, '<td valign="top">I could wonder why your favorite window is at a train depot, but rather I''m more entranced by the idea of all the little shows that must go on every time somebody uses the bench just outside.</td>', 'I could wonder why your favorite window is at a train depot, but rather I''m more entranced by the idea of all the little shows that must go on every time somebody uses the bench just outside.', '2011-09-01 19:35:22.000000', NULL, 1),
(6523832, 969350, 117912, '<td valign="top">There is so much of this hidden in darkness - the sun shining through the clouds is nice, but I don''t feel that it carries the picture by itself.</td>', 'There is so much of this hidden in darkness - the sun shining through the clouds is nice, but I don''t feel that it carries the picture by itself.', '2011-09-01 19:35:24.000000', NULL, 1),
(6523833, 969097, 117912, '<td valign="top">It''s a nice little courtyard, it must see plenty of people at times - I feel the picture might have been better if there was some more points of interest or was telling a story.</td>', 'It''s a nice little courtyard, it must see plenty of people at times - I feel the picture might have been better if there was some more points of interest or was telling a story.', '2011-09-01 19:35:26.000000', NULL, 1),
(6523834, 969276, 117912, '<td valign="top">Reflections add so much depth to the picture - I am immediately drawn in to trying to figure out whether what I''m seeing is a reflection - or even a reflection of a reflection.  Well seen and captured.</td>', 'Reflections add so much depth to the picture - I am immediately drawn in to trying to figure out whether what I''m seeing is a reflection - or even a reflection of a reflection.  Well seen and captured.', '2011-09-01 19:35:28.000000', NULL, 1),
(6523835, 969323, 117912, '<td valign="top">Spiders may be nearly a universal fear, but they''re also a good subject for a photo - I like how the lack of focus draws more into the contrast - both in lights and darks, and between large and fine shapes.</td>', 'Spiders may be nearly a universal fear, but they''re also a good subject for a photo - I like how the lack of focus draws more into the contrast - both in lights and darks, and between large and fine shapes.', '2011-09-01 19:35:29.000000', NULL, 1),
(6523836, 969361, 117912, '<td valign="top">Nicely spotted, keeping a web and droplets all in focus while having the background blurred is definitely a challenge - mostly in lining up the plane of focus with the web.  Well captured.</td>', 'Nicely spotted, keeping a web and droplets all in focus while having the background blurred is definitely a challenge - mostly in lining up the plane of focus with the web.  Well captured.', '2011-09-01 19:35:31.000000', NULL, 1),
(6523838, 968855, 117912, '<td valign="top">Without the clue from the title, I would not have recognized the site - indeed, even with the knowledge it is difficult to imagine from this point of view.  The sheer size of everything there is immense and belittling.</td>', 'Without the clue from the title, I would not have recognized the site - indeed, even with the knowledge it is difficult to imagine from this point of view.  The sheer size of everything there is immense and belittling.', '2011-09-01 19:35:33.000000', NULL, 1),
(6523839, 969356, 117912, '<td valign="top">Nice grain and a suggestion of form in the shadow and light - not sure about centering the point of interest though.</td>', 'Nice grain and a suggestion of form in the shadow and light - not sure about centering the point of interest though.', '2011-09-01 19:35:35.000000', NULL, 1),
(6523840, 969291, 117912, '<td valign="top">I like how the tree frames the little table.  It must be a pleasant space to spend some time.</td>', 'I like how the tree frames the little table.  It must be a pleasant space to spend some time.', '2011-09-01 19:35:37.000000', NULL, 1),
(6523841, 969242, 117912, '<td valign="top">Any view with hummingbirds is a charmer - and there doesn''t seem to be a shortage of them either.  I''m guessing the privacy screen is dual purpose for letting you photograph and see them as well as providing privacy.</td>', 'Any view with hummingbirds is a charmer - and there doesn''t seem to be a shortage of them either.  I''m guessing the privacy screen is dual purpose for letting you photograph and see them as well as providing privacy.', '2011-09-01 19:35:40.000000', NULL, 1),
(6523842, 968850, 117912, '<td valign="top">A little slice of life.  Nice focus and framing through the divided light.  I''m wondering what metering you were using as while there a couple of points at are full white, the majority of the image is so dark.</td>', 'A little slice of life.  Nice focus and framing through the divided light.  I''m wondering what metering you were using as while there a couple of points at are full white, the majority of the image is so dark.', '2011-09-01 19:35:41.000000', NULL, 1),
(6523844, 969154, 117912, '<td valign="top">Beautiful capture of a sunset, but the horizon being in the middle feels a little too heavy - especially when there are interesting clouds chopped of at the top.  I would have liked to see a bit more sky here as there just isn''t any interest in the bottom half of the frame.</td>', 'Beautiful capture of a sunset, but the horizon being in the middle feels a little too heavy - especially when there are interesting clouds chopped of at the top.  I would have liked to see a bit more sky here as there just isn''t any interest in the bottom half of the frame.', '2011-09-01 19:35:46.000000', NULL, 1),
(6523845, 969357, 117912, '<td valign="top">If every person has a story to tell, there are millions outside this window every day - imagine the combined knowledge that pours through this view...</td>', 'If every person has a story to tell, there are millions outside this window every day - imagine the combined knowledge that pours through this view...', '2011-09-01 19:35:47.000000', NULL, 1),
(6523846, 969304, 117912, '<td valign="top">Amazing fish-eye view - such a spectacular viewpoint.</td>', 'Amazing fish-eye view - such a spectacular viewpoint.', '2011-09-01 19:35:48.000000', NULL, 1),
(6523847, 969297, 117912, '<td valign="top">I have to wonder what this would look like with a fill flash to bring out the foreground.</td>', 'I have to wonder what this would look like with a fill flash to bring out the foreground.', '2011-09-01 19:35:50.000000', NULL, 1),
(6523850, 969294, 117912, '<td valign="top">Windows within windows - nice exploration of framing.  Both views are interesting on their own - combined though, they seem to be less than their sum.</td>', 'Windows within windows - nice exploration of framing.  Both views are interesting on their own - combined though, they seem to be less than their sum.', '2011-09-01 19:37:39.000000', NULL, 1),
(6523851, 969002, 117912, '<td valign="top">A glorious view.  Nice exposure to get the shading into the distance.</td>', 'A glorious view.  Nice exposure to get the shading into the distance.', '2011-09-01 19:37:43.000000', NULL, 1),
(6523852, 968662, 117912, '<td valign="top">Lovely bokeh and use of negative space - the silhouette at the bottom left is intriguing.</td>', 'Lovely bokeh and use of negative space - the silhouette at the bottom left is intriguing.', '2011-09-01 19:37:45.000000', NULL, 1),
(6523853, 969347, 117912, '<td valign="top">The composition is nice with the leading lines and subjects wonderfully placed but it seems a little underexposed to me.</td>', 'The composition is nice with the leading lines and subjects wonderfully placed but it seems a little underexposed to me.', '2011-09-01 19:37:46.000000', NULL, 1),
(6523854, 968243, 117912, '<td valign="top">Night exposures with the light juxtaposed always bring out the mystery.  The framing through the divided light adds a lot of interest and focus to the image.</td>', 'Night exposures with the light juxtaposed always bring out the mystery.  The framing through the divided light adds a lot of interest and focus to the image.', '2011-09-01 19:37:47.000000', NULL, 1),
(6523855, 969363, 117912, '<td valign="top">These windows certainly let in a beautiful view - they must take forever to clean ;-)  The slant of the lines feels a little out of balance though.</td>', 'These windows certainly let in a beautiful view - they must take forever to clean ;-)  The slant of the lines feels a little out of balance though.', '2011-09-01 19:37:48.000000', NULL, 1),
(6523856, 969070, 117912, '<td valign="top">This photo has so many great things going for it - the composition and framing are stunning, the planning is great - it looks like death is looking to move forth into the city.  The rim lighting really sets the figure forward from the windows - was it set a little too high maybe? it seems to have lit the left sleeve which is a distraction - I wonder where the scythe is...</td>', 'This photo has so many great things going for it - the composition and framing are stunning, the planning is great - it looks like death is looking to move forth into the city.  The rim lighting really sets the figure forward from the windows - was it set a little too high maybe? it seems to have lit the left sleeve which is a distraction - I wonder where the scythe is...', '2011-09-01 19:37:49.000000', NULL, 1),
(6523857, 969364, 117912, '<td valign="top">Morning before caffeine - i know the sight too well ;-)</td>', 'Morning before caffeine - i know the sight too well ;-)', '2011-09-01 19:38:00.000000', NULL, 1),
(6523860, 969267, 117912, '<td valign="top">Beautiful shot - excellent exposure - just a little reflection off the window in the lower right corner.  Such a scenic place to travel.</td>', 'Beautiful shot - excellent exposure - just a little reflection off the window in the lower right corner.  Such a scenic place to travel.', '2011-09-01 19:39:22.000000', NULL, 1),
(6523864, 969209, 117912, '<td valign="top">Driving and taking photographs - that explains being in the middle of the road... Timely and interesting capture.</td>', 'Driving and taking photographs - that explains being in the middle of the road... Timely and interesting capture.', '2011-09-01 19:41:49.000000', NULL, 1),
(6523871, 969196, 117912, '<td valign="top">Excellent capture - I like the bokeh of the background.</td>', 'Excellent capture - I like the bokeh of the background.', '2011-09-01 19:44:24.000000', NULL, 1),
