INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6527480, 969300, 128323, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Cyberlandz:</b></div><hr/><i> Great image. Congrats on the blue. Man i wish you did not mention the sharpen. It''s not allowed in minimal editing. </i></td></tr></table> <br/> <br/>I double-checked the "minimal editing" rules, and sharpening is allowed, but just simple sharpening.  The rule states:<br/> <br/>You may:<br/> <br/>sharpen your entry using your editing softwares sharpen or equivalent option. The use of customizable sharpening tools, such as Unsharp Mask, is not allowed.<br/></td>', 'Originally posted by Cyberlandz: Great image. Congrats on the blue. Man i wish you did not mention the sharpen. It''s not allowed in minimal editing.   I double-checked the "minimal editing" rules, and sharpening is allowed, but just simple sharpening.  The rule states: You may: sharpen your entry using your editing softwares sharpen or equivalent option. The use of customizable sharpening tools, such as Unsharp Mask, is not allowed.', '2011-09-04 14:20:13.000000', NULL, 0),
(6527893, 969300, 85430, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ecmguy:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Cyberlandz:</b></div><hr/><i> Great image. Congrats on the blue. Man i wish you did not mention the sharpen. It''s not allowed in minimal editing. </i></td></tr></table> <br/> <br/>I double-checked the "minimal editing" rules, and sharpening is allowed, but just simple sharpening.  The rule states:<br/> <br/>You may:<br/> <br/>sharpen your entry using your editing softwares sharpen or equivalent option. The use of customizable sharpening tools, such as Unsharp Mask, is not allowed. </i></td></tr></table> <br/> <br/>in that case i stand corrected. Congrats again. Well deserved. No doubt about it now :)</td>', 'Originally posted by ecmguy: Originally posted by Cyberlandz: Great image. Congrats on the blue. Man i wish you did not mention the sharpen. It''s not allowed in minimal editing.   I double-checked the "minimal editing" rules, and sharpening is allowed, but just simple sharpening.  The rule states: You may: sharpen your entry using your editing softwares sharpen or equivalent option. The use of customizable sharpening tools, such as Unsharp Mask, is not allowed.   in that case i stand corrected. Congrats again. Well deserved. No doubt about it now :)', '2011-09-04 22:15:24.000000', NULL, 0),
(6528628, 969300, 103142, '<td valign="top">wow!! Way to get a first ribbon!! Smashing your personal best with an incredible shot!! Congrats!</td>', 'wow!! Way to get a first ribbon!! Smashing your personal best with an incredible shot!! Congrats!', '2011-09-05 07:29:09.000000', NULL, 0),
(6528630, 969260, 103142, '<td valign="top">I hope you had a remote. I did this type of shot awhile ago, and I''d have to go out, spray the window, run back in and push the button. Most of the time the water was already gone! Never heard of rainx -- I''ll have to tuck that piece of info away for future use. :)</td>', 'I hope you had a remote. I did this type of shot awhile ago, and I''d have to go out, spray the window, run back in and push the button. Most of the time the water was already gone! Never heard of rainx -- I''ll have to tuck that piece of info away for future use. :)', '2011-09-05 07:32:00.000000', NULL, 0),
(6528631, 969295, 103142, '<td valign="top">Congrats on the yellow!!</td>', 'Congrats on the yellow!!', '2011-09-05 07:32:28.000000', NULL, 0),
(6529455, 969300, 4793, '<td valign="top">Nice</td>', 'Nice', '2011-09-05 20:05:28.000000', NULL, 0),
